import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        // Event key 2*time+bit: bit 1 for a start, 0 for the moment after an end,
        // so ends sort before starts at equal times.
        long[] events = new long[2 * n];
        for (int i = 0; i < n; i++) {
            long l = next(), h = next();
            events[2 * i] = 2 * l + 1;
            events[2 * i + 1] = 2 * (h + 1);
        }
        Arrays.sort(events);
        int active = 0, answer = 0;
        for (long e : events) {
            active += (e & 1) == 1 ? 1 : -1;
            answer = Math.max(answer, active);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(next())
	// Event key 2*time+bit: bit 1 for a start, 0 for the moment after an end,
	// so ends sort before starts at equal times.
	events := make([]int64, 0, 2*n)
	for i := 0; i < n; i++ {
		l, h := next(), next()
		events = append(events, 2*l+1, 2*(h+1))
	}
	slices.Sort(events)
	active, answer := 0, 0
	for _, e := range events {
		if e&1 == 1 {
			active++
		} else {
			active--
		}
		answer = max(answer, active)
	}
	fmt.Println(answer)
}
